// @ts-check
// Renders lib/theme/tokens.json for each surface: Swift for the Capsule, TypeScript for the Expo
// app, CSS custom properties for the Deck. Pure functions of the JSON, so the outputs are
// byte-for-byte stable and a test can say when one is stale. The JSON, rgba and the CSS renderer
// live in lib/theme (vyred uses them at run time); this file adds the build-only renderers.
import fs from "node:fs";
import path from "node:path";
import { rgba, css as renderCss, SOURCE } from "../../lib/theme/index.js";

export { rgba };
export const TOKENS = SOURCE;
// The generated files still name the token source's old home in their first line, so moving the
// JSON left every output byte-for-byte the same. Changing this line regenerates all three.
const NAMED = "docs/design/one-app/tokens.json";

/** @param {string} root */
export function load(root) {
  return JSON.parse(fs.readFileSync(path.join(root, TOKENS), "utf8"));
}

const num = n => (Number.isInteger(n) ? String(n) : String(n));
const swiftColor = v => { const [r, g, b, a] = rgba(v); return `Color(.sRGB, red: ${r} / 255, green: ${g} / 255, blue: ${b} / 255, opacity: ${num(a)})`; };
const kebab = k => k.replace(/[A-Z0-9]/g, (c, i) => (i ? "-" : "") + c.toLowerCase());
const HEAD_V2 = "Deck v2 tokens, generated by scripts/gen-tokens from tokens.v2 in lib/theme/tokens.json. Do not edit; change the JSON and run it. The names are new (--surface-1, --edge, --s-4 ...) and this sheet loads after tokens.css.";
const HEAD = `Generated by scripts/gen-tokens from ${NAMED}. Do not edit; change the JSON and run it.`;

/** The Capsule's Swift file. */
export function swift(t) {
  const keys = Object.keys(t.color.dark);
  const colors = theme => keys.map(k => `        ${k}: ${swiftColor(t.color[theme][k])}`).join(",\n");
  const alt = Object.entries(t.color.attentionAlt)
    .map(([name, v]) => `        "${name}": (${swiftColor(v.dark)}, ${swiftColor(v.paper)})`).join(",\n");
  const status = t.status.order.map(k => {
    const s = t.status[k];
    return `        Status(key: "${k}", mark: "${s.mark}", color: "${s.color}", word: "${s.word}")`;
  }).join(",\n");
  const enumOf = (name, obj, type = "CGFloat") =>
    `    public enum ${name} {\n${Object.entries(obj).map(([k, v]) => `        public static let ${k}: ${type} = ${num(v)}`).join("\n")}\n    }`;
  const typeScale = Object.entries(t.type.desktop)
    .map(([k, [size, line]]) => `        public static let ${k}: (size: CGFloat, line: CGFloat) = (${size}, ${line})`).join("\n");
  const phoneScale = Object.entries(t.type.phone)
    .map(([k, [size, line]]) => `        public static let ${k}: (size: CGFloat, line: CGFloat) = (${size}, ${line})`).join("\n");
  const { ease, ...motion } = t.motion;
  return `// ${HEAD}
// The Capsule reads these through Theme.swift; the app and the Deck read the same JSON.

import SwiftUI

public enum Tokens {
    public struct Colors: Sendable {
${keys.map(k => `        public let ${k}: Color`).join("\n")}
    }

    public static let dark = Colors(
${colors("dark")}
    )

    public static let paper = Colors(
${colors("paper")}
    )

    /// The attention colour when the person picks another than beacon (violet).
    public static let attentionAlt: [String: (dark: Color, paper: Color)] = [
${alt}
    ]

    public struct Status: Equatable, Sendable {
        public let key: String, mark: String, color: String, word: String
    }
    /// Most urgent first: a row shows the first that applies. The keys are a stable contract.
    public static let status: [Status] = [
${status}
    ]

${enumOf("Radius", t.radius)}

${enumOf("Control", t.control)}

    public static let space: [CGFloat] = [${t.space.join(", ")}]

    /// Durations in milliseconds, and the easing curve's control points.
    public enum Motion {
${Object.entries(motion).map(([k, v]) => `        public static let ${k}: Double = ${num(v)}`).join("\n")}
        public static let ease: [Double] = [${ease.join(", ")}]
    }

    /// [size, line height] in points, desktop and the Capsule.
    public enum TypeScale {
${typeScale}
    }

    /// [size, line height] in points on a phone: the read and title steps are two larger.
    public enum PhoneTypeScale {
${phoneScale}
    }

    /// Sizes JetBrains Mono may use, in points.
    public static let monoSizes: [CGFloat] = [${t.type.mono.join(", ")}]

    public static let fontSans = "${t.font.sans}"
    public static let fontMono = "${t.font.mono}"

${swiftV2(t.v2)}
}
`;
}

const em = v => Number.parseFloat(v);

/** Deck v2 for Swift: Tokens.V2, nested in Tokens. Colours, type, shape, motion, elevation and the project emblem, as plain values. @param {any} v */
function swiftV2(v) {
  const roles = Object.keys(v.color.dark);
  const colors = theme => roles.map(k => `            ${k}: ${swiftColor(v.color[theme][k])}`).join(",\n");
  const enumOf = (name, obj, type = "CGFloat") =>
    `        public enum ${name} {\n${Object.entries(obj).map(([k, x]) => `            public static let ${k}: ${type} = ${num(x)}`).join("\n")}\n        }`;
  const scale = (name, set) =>
    `        public enum ${name} {\n${Object.entries(set).filter(([, x]) => Array.isArray(x)).map(([k, [size, line]]) => `            public static let ${k}: (size: CGFloat, line: CGFloat) = (${size}, ${line})`).join("\n")}\n            public static let label: CGFloat = ${set.label}\n        }`;
  const spring = set => Object.entries(set).map(([k, x]) => `                public static let ${k === "default" ? "`default`" : k} = Spring(damping: ${num(x.damping)}, stiffness: ${num(x.stiffness)})`).join("\n");
  const layer = ([x, y, blur, spread, color, inset], theme) =>
    `Layer(x: ${x}, y: ${y}, blur: ${blur}, spread: ${spread}, color: ${swiftColor(v.color[theme][color] || color)}, inset: ${inset})`;
  const elevation = theme => Object.entries(v.elevation[theme])
    .map(([k, layers]) => `                public static let ${k}: [Layer] = [${layers.map(l => layer(l, theme)).join(", ")}]`).join("\n");
  const op = o => {
    const n = o.slice(1).map(num);
    return o[0] === "M" ? `.move(${n.join(", ")})` : o[0] === "L" ? `.line(${n.join(", ")})`
      : o[0] === "A" ? `.arc(rx: ${n[0]}, ry: ${n[1]}, rotation: ${n[2]}, large: ${n[3] === "1"}, sweep: ${n[4] === "1"}, x: ${n[5]}, y: ${n[6]})` : ".close";
  };
  const shape = s => s.kind === "circle" ? `.circle(cx: ${s.cx}, cy: ${s.cy}, r: ${s.r})`
    : s.kind === "rect" ? `.rect(x: ${s.x}, y: ${s.y}, w: ${s.w}, h: ${s.h}, rx: ${s.rx})`
    : s.kind === "ring" ? `.ring(cx: ${s.cx}, cy: ${s.cy}, r: ${s.r}, stroke: ${s.stroke})`
    : `.path([${s.ops.map(op).join(", ")}], rotates: ${s.rotates})`;
  const e = v.emblem, m = v.motion;
  return `    /// Deck v2 (design-system.md): the tokens the redesigned Deck, the phone app and the Capsule share.
    public enum V2 {
        public struct Colors: Sendable {
${roles.map(k => `            public let ${k}: Color`).join("\n")}
        }

        public static let dark = Colors(
${colors("dark")}
        )

        public static let paper = Colors(
${colors("paper")}
        )

${enumOf("Radius", v.radius)}

${enumOf("Control", v.control)}

${enumOf("Layout", v.layout)}

        public static let space: [CGFloat] = [${v.space.join(", ")}]

        /// [size, line height] in points: desktop and the Capsule, then a phone.
${scale("TypeScale", v.type.desktop)}

${scale("PhoneTypeScale", v.type.phone)}

        /// Letter spacing in em.
        public enum Tracking {
${Object.entries(v.type.tracking).map(([k, x]) => `            public static let ${k}: CGFloat = ${em(x)}`).join("\n")}
        }

        public static let weights: [Int] = [${v.font.weight.join(", ")}]

        public struct Spring: Equatable, Sendable { public let damping: Double, stiffness: Double }

        public struct Layer: Sendable { public let x: CGFloat, y: CGFloat, blur: CGFloat, spread: CGFloat, color: Color, inset: Bool }

        /// Durations in milliseconds, easing control points, springs and the row stagger.
        public enum Motion {
${Object.entries(m.duration).map(([k, x]) => `            public static let ${k}: Double = ${num(x)}`).join("\n")}
            public static let hold: Double = ${num(m.hold)}
            public static let undo: Double = ${num(m.undo)}
${Object.entries(m.easing).map(([k, x]) => `            public static let ${k}Ease: [Double] = [${x.join(", ")}]`).join("\n")}
            public static let staggerStep: Double = ${m.stagger.step}
            public static let staggerMax: Int = ${m.stagger.max}
            public enum Spatial {
${spring(m.spring.spatial)}
            }
            public enum Effects {
${spring(m.spring.effects)}
            }
        }

        /// Three shadow levels, each a list of layers, per scheme.
        public enum Elevation {
            public enum Dark {
${elevation("dark")}
            }
            public enum Paper {
${elevation("paper")}
            }
        }

        public enum Icon {
            public static let grid: CGFloat = ${v.icon.grid}
            public static let size: CGFloat = ${v.icon.size}
            public static let stroke: CGFloat = ${v.icon.stroke}
        }

        /// The project emblem: draw it from the project's eight seed bytes (see the rules below). Coordinates are in a ${e.canvas} unit canvas.
        public enum Emblem {
            public enum Op: Equatable, Sendable {
                case move(CGFloat, CGFloat), line(CGFloat, CGFloat), close
                case arc(rx: CGFloat, ry: CGFloat, rotation: CGFloat, large: Bool, sweep: Bool, x: CGFloat, y: CGFloat)
            }
            public enum Shape: Equatable, Sendable {
                case circle(cx: CGFloat, cy: CGFloat, r: CGFloat)
                case rect(x: CGFloat, y: CGFloat, w: CGFloat, h: CGFloat, rx: CGFloat)
                case ring(cx: CGFloat, cy: CGFloat, r: CGFloat, stroke: CGFloat)
                case path([Op], rotates: Bool)
            }
${["canvas", "cell", "corner", "inset"].map(k => `            public static let ${k}: CGFloat = ${e[k]}`).join("\n")}
            public static let cells: [(x: CGFloat, y: CGFloat)] = [${e.cells.map(([x, y]) => `(${x}, ${y})`).join(", ")}]
            public static let palette: [Color] = [${e.palette.map(swiftColor).join(", ")}]
            public static let inkDark = ${swiftColor(e.ink.dark)}
            public static let inkPaper = ${swiftColor(e.ink.paper)}
            public static let draftDash: [CGFloat] = [${e.draft.dash.join(", ")}]
            public static let draftStroke: CGFloat = ${e.draft.stroke}
            public static let draftFrame: CGFloat = ${e.draft.frame}
            public static let draftCellOpacity: Double = ${e.draft.cellOpacity}
            /// Shape i is chosen by b[2 + cell] % ${e.shapes.length}.
            public static let shapes: [Shape] = [
${e.shapes.map(s => `                ${shape(s)}`).join(",\n")}
            ]
${e.rules.map(r => `            // ${r}`).join("\n")}
        }
    }`;
}

/** The Expo app's tokens.ts (apps/app/src/theme/tokens.ts): the JSON as a frozen `as const`
 * object, minus the note, plus `attention(scheme, alt)` so the violet/teal choice stays one key. */
export function ts(t) {
  const { $schema, note, ...rest } = t;
  void $schema; void note;
  return `// Generated by scripts/gen-tokens from ${NAMED}. Do not edit; change the JSON and run it.

export const tokens = ${JSON.stringify(rest, null, 2)} as const;

export type Scheme = "dark" | "paper";
export type Colors = typeof tokens.color.dark;

/** The attention colour: beacon (violet) by default, or an alternative such as teal. */
export function attention(scheme: Scheme, alt?: keyof typeof tokens.color.attentionAlt): string {
  return alt ? tokens.color.attentionAlt[alt][scheme] : tokens.color[scheme].beacon;
}
`;
}

/** The Deck's roles as custom properties (deck/css/tokens.css); the renderer is lib/theme's css(). @param {any} t */
export const css = t => renderCss(t, HEAD);

const PX = n => `${num(n)}px`;
const cssColor = c => c.replace(/\s+/g, "").replace(/(\D)0\./g, "$1.");

/** One elevation as a box-shadow list; a colour that names a role is that role's variable. */
const shadow = layers => layers.map(([x, y, blur, spread, color, inset]) => {
  const c = /^(rgba?\(|#)/.test(color) ? cssColor(color) : `var(--${kebab(color)})`;
  return `${x}${x ? "px" : ""} ${y}${y ? "px" : ""} ${blur}${blur ? "px" : ""}${spread ? ` ${spread}px` : ""} ${c}${inset ? " inset" : ""}`;
}).join(", ");

/**
 * The Deck v2 roles as custom properties (deck/css/tokens-v2.css), from tokens.v2. The names are the
 * Deck's (--surface-1, --edge, --s-4, --r-card, --elev-2). It loads after tokens.css and wins.
 * @param {any} t
 */
export function cssV2(t) {
  const v = t.v2;
  const roles = theme => Object.entries(v.color[theme]).map(([k, x]) => `  --${kebab(k)}: ${cssColor(x)};`).join("\n");
  const elev = theme => Object.entries(v.elevation[theme]).filter(([k]) => k !== "note").map(([k, layers]) => `  --elev-${k.slice(1)}: ${shadow(layers)};`).join("\n");
  const d = v.type.desktop, p = v.type.phone;
  const step = (k, set) => `--fs-${k}: ${set[k][0]}px; --lh-${k}: ${set[k][1]}px;`;
  const names = Object.keys(d).filter(k => Array.isArray(d[k]));
  const phoneSteps = names.filter(k => d[k].join() !== p[k].join());
  const m = v.motion, c = v.control, L = v.layout;
  const curve = a => `cubic-bezier(${a.join(",")})`;
  return `/* ${HEAD_V2} */

:root {
  /* colour roles */
${roles("dark")}
  /* type */
  --sans: '${t.font.sans}', 'Helvetica Neue', Arial, sans-serif;
  --mono: '${t.font.mono}', ui-monospace, Menlo, monospace;
${names.map(k => "  " + step(k, d)).join("\n")}
  --fs-label: ${d.label}px;
  /* space: a 4 grid */
  ${v.space.filter(x => x).map(x => `--s-${x / 4}: ${x}px;`).join(" ")}
  /* shape */
  ${Object.entries(v.radius).map(([k, x]) => `--r-${kebab(k)}: ${x}px;`).join(" ")}
  /* elevation: three levels, nothing else casts a shadow */
${elev("dark")}
  /* motion */
  --dur-1: ${m.duration.press}ms; --dur-2: ${m.duration.state}ms; --dur-3: ${m.duration.panel}ms; --dur-4: ${m.duration.sheet}ms; --dur-nod: ${m.duration.nod}ms;
  --ease: ${curve(m.easing.standard)}; --ease-io: ${curve(m.easing.inOut)}; --spring: ${curve(m.easing.spring)};
  /* layout */
  --rail-w: ${PX(L.rail)}; --list-w: ${PX(L.list)}; --side-w: ${PX(L.side)}; --page-max: ${PX(L.pageMax)}; --read-max: ${PX(L.readMax)};
  --control: ${PX(c.md)}; --control-sm: ${PX(c.sm)}; --row-h: ${PX(c.row)};
  color-scheme: dark;
}
:root[data-theme="paper"] {
${roles("paper")}
${elev("paper")}
  color-scheme: light;
}

/* Phone: larger body, read and title, 44 px controls and 64 px rows (design-system.md, type table). */
@media (max-width: ${t.layout.breakpoints.medium - 1}px), (max-height: 500px) and (pointer: coarse) {
  :root { ${phoneSteps.map(k => step(k, p)).join(" ")} --control: ${PX(c.touch)}; --control-sm: ${PX(c.touchSm)}; --row-h: ${PX(c.rowPhone)}; }
}
`;
}

const HEAD_V3 = "Deck v3 tokens, generated by scripts/gen-tokens from tokens.v3 in lib/theme/tokens.json. Do not edit; change the JSON and run it. It loads after tokens-v2.css and only scales or swaps what a space or a person may configure (density, font, corners); deck/ui/theme.js sets the root attributes and the accent.";

/**
 * Deck v3: the configurable layer over v2. Space, shapes and the body size scale with the density step, radii with the corners step, and the
 * sans family swaps with the font step. A step is chosen by an attribute on the root (data-density, data-font, data-corners); with none set
 * every value equals v2. Control sizes and the body size change only from 720 px up: a phone keeps its 44 px targets and its 16 px body.
 * @param {any} t
 */
export function cssV3(t) {
  const v = t.v3, v2 = t.v2;
  const D = v.density.steps, C = v.corners.steps;
  const spaceVars = v.spaceSteps.map(/** @param {number} n */ n => `  --s-${n}: calc(${n * 4}px * var(--density));`).join("\n");
  const radii = v.corners.applies.map(/** @param {string} k */ k => `  --r-${kebab(k)}: calc(${v2.radius[k]}px * var(--corner));`).join("\n");
  const dens = Object.entries(D).map(([k, d]) => `:root[data-density="${k}"] { --density: ${d.space}; }`).join("\n");
  const densDesk = Object.entries(D).map(([k, d]) =>
    `  :root[data-density="${k}"] { --control: ${d.control}px; --control-sm: ${d.controlSm}px; --row-h: ${d.row}px; --fs-body: ${d.body[0]}px; --lh-body: ${d.body[1]}px; }`).join("\n");
  const corners = Object.entries(C).map(([k, x]) => `:root[data-corners="${k}"] { --corner: ${x}; }`).join("\n");
  const fonts = Object.entries(v.font.stacks).filter(([k]) => k !== v.font.default).map(([k, f]) => `:root[data-font="${k}"] { --sans: ${f.css}; }`).join("\n");
  return `/* ${HEAD_V3} */

:root {
  --density: ${D[v.density.default].space};
  --corner: ${C[v.corners.default]};
${spaceVars}
${radii}
}
${dens}
${corners}
${fonts}
@media (min-width: ${t.layout.breakpoints.medium}px) and (min-height: 501px), (min-width: ${t.layout.breakpoints.medium}px) and (pointer: fine), (min-width: ${t.layout.breakpoints.medium}px) and (pointer: none) {
${densDesk}
}
`;
}

/** The v3 table as an ES module for the Deck (deck/ui/theme.js reads it): the same JSON, never a second copy. @param {any} t */
export const jsV3 = t => `// Generated by scripts/gen-tokens from tokens.v3 in lib/theme/tokens.json. Do not edit; change the JSON and run it.

export const V3 = ${JSON.stringify(t.v3, null, 2)};
`;
